import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/index.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

test('reports a string rejection with its cause while preserving the caller rejection [specs/hal-engine-config-hooks/spec.md#8]', async () => {
  const errors: Error[] = [];
  const session: ChatSession = {sessionId: 'rejection', userId: 'user', entries: []};
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'Test assistant'}),
    undefined,
    {
      hooks: {
        beforeSession: () => Promise.reject('string boom'),
        onError: async (_session, error) => {
          errors.push(error);
        },
      },
    }
  );

  const rejection: unknown = await orchestrator.processMessage(session).catch((reason: unknown) => reason);

  expect({count: errors.length, isError: errors[0] instanceof Error, message: errors[0]?.message, cause: errors[0]?.cause, rejection}).toEqual({
    count: 1,
    isError: true,
    message: 'string boom',
    cause: 'string boom',
    rejection: 'string boom',
  });
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/chatOrchestrator.rejection.test.ts"
